import React from "react";
import { Link } from "react-router-dom";
import pupImg from "../img/pup.jpg";

const HomePage = () => {
  return (
    <div
      style={{
        backgroundImage: `url(${pupImg})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: "#fff",
        textShadow: "2px 2px 4px rgba(0,0,0,0.7)",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(0,0,0,0.6)",
          padding: "40px",
          borderRadius: "16px",
          textAlign: "center",
          maxWidth: "500px",
          width: "90%",
        }}
      >
        <h1 style={{ fontSize: "3rem", marginBottom: "20px" }}>
          📘 Welcome to <br /> <span style={{ color: "#FFD700" }}>PUP-OUS Exam Generator</span>
        </h1>
        <p style={{ fontSize: "1.2rem", marginBottom: "30px" }}>
          Seamlessly create, manage, and take exams anytime, anywhere.
        </p>
        <div style={{ display: "flex", gap: "20px", justifyContent: "center" }}>
          <Link to="/signin">
            <button
              style={{
                backgroundColor: "#FFD700",
                color: "#000",
                border: "none",
                padding: "12px 24px",
                fontSize: "1rem",
                borderRadius: "8px",
                cursor: "pointer",
              }}
            >
              Login
            </button>
          </Link>
          <Link to="/signup">
            <button
              style={{
                backgroundColor: "#fff",
                color: "#000",
                border: "none",
                padding: "12px 24px",
                fontSize: "1rem",
                borderRadius: "8px",
                cursor: "pointer",
              }}
            >
              Sign Up
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default HomePage;
